create table if not exists public.local_admin_notification_settings(event_type text primary key,enabled boolean not null default true,cadence text not null default 'immediate' check(cadence in ('immediate','hourly','daily','weekly')));
insert into public.local_admin_notification_settings(event_type,enabled,cadence) values ('registration',true,'immediate'),('member_report',true,'immediate'),('venue_request',true,'immediate'),('marketplace_report',true,'immediate'),('event_review',true,'immediate'),('security',true,'immediate'),('technical',true,'immediate'),('daily_summary',false,'daily'),('weekly_summary',false,'weekly') on conflict do nothing;
create table if not exists public.local_admin_notifications(id uuid primary key default gen_random_uuid(),event_type text not null references public.local_admin_notification_settings(event_type),subject text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),deliver_after timestamptz not null default now(),status text not null default 'pending',attempts int not null default 0,last_error text,sent_at timestamptz,locked_at timestamptz);
create index if not exists local_admin_notify_queue on public.local_admin_notifications(status,deliver_after);
alter table public.local_admin_notification_settings enable row level security;
alter table public.local_admin_notifications enable row level security;
drop policy if exists local_notify_read_settings on public.local_admin_notification_settings;
create policy local_notify_read_settings on public.local_admin_notification_settings for select to authenticated using(public.is_local_admin());
drop policy if exists local_notify_update_settings on public.local_admin_notification_settings;
create policy local_notify_update_settings on public.local_admin_notification_settings for update to authenticated using(public.is_local_admin()) with check(public.is_local_admin());
drop policy if exists local_notify_read_alerts on public.local_admin_notifications;
create policy local_notify_read_alerts on public.local_admin_notifications for select to authenticated using(public.is_local_admin());
grant select,update on public.local_admin_notification_settings to authenticated;
grant select on public.local_admin_notifications to authenticated;
revoke insert,update,delete on public.local_admin_notifications from anon,authenticated;
create or replace function public.local_notify_registration() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.local_admin_notifications(event_type,subject,details) values('registration','New member registration',jsonb_build_object('member_id',new.id,'member_email',new.email,'member_name',coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'full_name','New member'),'registered_at',new.created_at,'verified',new.email_confirmed_at is not null));return new;end $$;
drop trigger if exists local_notify_new_registration on auth.users;
create trigger local_notify_new_registration after insert on auth.users for each row execute function public.local_notify_registration();
create or replace function public.local_notify_queue(p_type text,p_subject text,p_details jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid;begin if auth.role()<>'service_role' then raise exception 'Service role required';end if;insert into public.local_admin_notifications(event_type,subject,details) values(p_type,left(p_subject,180),coalesce(p_details,'{}'::jsonb)) returning id into v_id;return v_id;end $$;
revoke all on function public.local_notify_queue(text,text,jsonb) from public,anon,authenticated;
grant execute on function public.local_notify_queue(text,text,jsonb) to service_role;
create or replace function public.local_notify_claim(p_limit int default 20) returns setof public.local_admin_notifications language plpgsql security definer set search_path=public,pg_temp as $$ begin if auth.role()<>'service_role' then raise exception 'Service role required';end if;return query with chosen as(select n.id from public.local_admin_notifications n where ((n.status in ('pending','failed') and n.deliver_after<=now()) or(n.status='processing' and n.locked_at<now()-interval '10 minutes')) and n.attempts<5 order by n.created_at limit least(greatest(p_limit,1),50) for update skip locked) update public.local_admin_notifications n set status='processing',locked_at=now(),attempts=n.attempts+1 from chosen where n.id=chosen.id returning n.*;end $$;
revoke all on function public.local_notify_claim(int) from public,anon,authenticated;
grant execute on function public.local_notify_claim(int) to service_role;
